with d as (select value r from jsonb_array_elements($q$[{"slug":"chicken-shish-bulgur-pilaf","title":"Chicken Shish with Bulgur Pilaf","cuisine":"turkish","meal_types":["dinner"],"diets":[],"difficulty":"medium","total_minutes":80,"recipe":{"id":"chicken-shish-bulgur-pilaf","title":"Chicken Shish with Bulgur Pilaf","summary":"Yoghurt and pepper-paste marinated chicken skewers over a buttery tomato bulgur pilaf.","cuisine":"turkish","diets":[],"mealTypes":["dinner"],"difficulty":"medium","prepMinutes":45,"cookMinutes":35,"servings":4,"onePot":false,"seasons":["spring","summer"],"ingredientGroups":[{"title":"Chicken","items":[{"item":"chicken thigh fillets","raw":"800g chicken thigh fillets, cut into 3cm pieces","quantity":800,"unit":"g","ingredientId":"chicken-thigh","prep":"cut into 3cm pieces"},{"item":"Greek yoghurt","raw":"100g Greek yoghurt","quantity":100,"unit":"g","ingredientId":"greek-yoghurt"},{"item":"tomato paste","raw":"1 tbsp tomato paste","quantity":1,"unit":"tbsp","ingredientId":"tomato-paste"},{"item":"Aleppo pepper","raw":"2 tsp Aleppo pepper (or 1 tsp sweet paprika and a pinch of chilli flakes)","quantity":2,"unit":"tsp","ingredientId":"aleppo-pepper","note":"or 1 tsp sweet paprika and a pinch of chilli flakes"},{"item":"ground cumin","raw":"1 tsp ground cumin","quantity":1,"unit":"tsp","ingredientId":"ground-cumin"},{"item":"garlic","raw":"2 garlic cloves, crushed","quantity":2,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"lemon","raw":"Juice of 1/2 lemon","quantity":0.5,"ingredientId":"lemon","prep":"juiced"},{"item":"olive oil","raw":"2 tbsp olive oil","quantity":2,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"}]},{"title":"Bulgur pilaf","items":[{"item":"butter","raw":"30g butter","quantity":30,"unit":"g","ingredientId":"butter"},{"item":"brown onion","raw":"1 brown onion, finely diced","quantity":1,"ingredientId":"brown-onion","prep":"finely diced"},{"item":"tomato paste","raw":"1 tbsp tomato paste","quantity":1,"unit":"tbsp","ingredientId":"tomato-paste"},{"item":"coarse bulgur","raw":"300g coarse bulgur, rinsed","quantity":300,"unit":"g","ingredientId":"bulgur","prep":"rinsed"},{"item":"chicken stock","raw":"600ml chicken stock","quantity":600,"unit":"ml","ingredientId":"chicken-stock"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"}]},{"title":"To serve","items":[{"item":"tomatoes","raw":"2 tomatoes, diced","quantity":2,"ingredientId":"tomato","prep":"diced"},{"item":"Lebanese cucumber","raw":"1 Lebanese cucumber, diced","quantity":1,"ingredientId":"cucumber","prep":"diced"},{"item":"red onion","raw":"1/2 red onion, thinly sliced","quantity":0.5,"ingredientId":"red-onion","prep":"thinly sliced"},{"item":"sumac","raw":"1 tsp sumac","quantity":1,"unit":"tsp","ingredientId":"sumac"},{"item":"flat-leaf parsley leaves","raw":"Handful of flat-leaf parsley leaves","quantity":1,"unit":"handful","ingredientId":"parsley"},{"item":"Greek yoghurt","raw":"150g Greek yoghurt","quantity":150,"unit":"g","ingredientId":"greek-yoghurt"}]}],"steps":[{"text":"Mix the chicken with the yoghurt, tomato paste, Aleppo pepper, cumin, garlic, lemon juice, oil and salt. Cover and refrigerate for at least 30 minutes, or up to a day. If using bamboo skewers, soak them in water now."},{"text":"For the pilaf, melt the butter in a saucepan over medium heat and cook the onion for 6 minutes until soft. Stir in the tomato paste for 1 minute, then the bulgur. Add the stock and salt, bring to the boil, cover and cook on the lowest heat for 15 minutes. Turn off the heat, lay a tea towel under the lid and rest for 10 minutes."},{"text":"Thread the chicken onto skewers. Heat a chargrill pan or barbecue over medium-high heat and cook the skewers for 10 to 12 minutes, turning every few minutes, until charred and cooked through (75°C in the thickest piece)."},{"text":"Toss the tomato, cucumber and red onion with the sumac and parsley."},{"text":"Fluff the pilaf with a fork and serve with the skewers, the salad and a spoonful of yoghurt."}],"notes":["Coarse bulgur is the one for pilaf. Fine bulgur is for tabbouleh and goes mushy here.","Turkish red pepper paste (biber salçası) is excellent instead of the tomato paste if you can find it.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"source":"user","provenance":"ai-draft"}},{"slug":"mujadara","title":"Mujadara","cuisine":"middle-eastern","meal_types":["dinner","lunch"],"diets":["vegetarian","vegan","no-gluten","no-dairy"],"difficulty":"easy","total_minutes":65,"recipe":{"id":"mujadara","title":"Mujadara","summary":"Lentils and rice cooked with cumin under a tangle of deeply caramelised crispy onions.","cuisine":"middle-eastern","diets":["vegetarian","vegan","no-gluten","no-dairy"],"mealTypes":["dinner","lunch"],"difficulty":"easy","prepMinutes":10,"cookMinutes":55,"servings":4,"onePot":false,"seasons":["autumn","winter"],"ingredientGroups":[{"title":"Onions","items":[{"item":"large brown onions","raw":"3 large brown onions, halved and thinly sliced","quantity":3,"ingredientId":"brown-onion","prep":"halved and thinly sliced"},{"item":"olive oil","raw":"80ml olive oil","quantity":80,"unit":"ml","ingredientId":"olive-oil"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"}]},{"title":"Lentils and rice","items":[{"item":"brown lentils","raw":"200g brown lentils, rinsed","quantity":200,"unit":"g","ingredientId":"brown-lentils","prep":"rinsed"},{"item":"basmati rice","raw":"200g basmati rice, rinsed","quantity":200,"unit":"g","ingredientId":"basmati-rice","prep":"rinsed"},{"item":"ground cumin","raw":"1 tsp ground cumin","quantity":1,"unit":"tsp","ingredientId":"ground-cumin"},{"item":"ground cinnamon","raw":"1/2 tsp ground cinnamon","quantity":0.5,"unit":"tsp","ingredientId":"ground-cinnamon"},{"item":"ground allspice","raw":"1/2 tsp ground allspice","quantity":0.5,"unit":"tsp","ingredientId":"allspice"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"water","raw":"500ml water","quantity":500,"unit":"ml","ingredientId":"water"}]},{"title":"Salad","items":[{"item":"tomatoes","raw":"2 tomatoes, diced","quantity":2,"ingredientId":"tomato","prep":"diced"},{"item":"Lebanese cucumber","raw":"1 Lebanese cucumber, diced","quantity":1,"ingredientId":"cucumber","prep":"diced"},{"item":"flat-leaf parsley","raw":"Handful of flat-leaf parsley, chopped","quantity":1,"unit":"handful","ingredientId":"parsley","prep":"chopped"},{"item":"lemon","raw":"Juice of 1/2 lemon","quantity":0.5,"ingredientId":"lemon","prep":"juiced"},{"item":"olive oil","raw":"1 tbsp olive oil","quantity":1,"unit":"tbsp","ingredientId":"olive-oil"}]},{"title":"To serve","items":[{"item":"Greek yoghurt","raw":"Greek yoghurt (optional)","ingredientId":"greek-yoghurt","optional":true}]}],"steps":[{"text":"Put the lentils in a saucepan, cover with plenty of cold water and bring to the boil. Simmer for 15 minutes, until just tender but not falling apart. Drain."},{"text":"Meanwhile, heat the oil in a large frying pan over medium-high heat. Add the onions and salt and cook for 25 to 30 minutes, stirring often and turning the heat down as they colour, until deep brown and some are crisp. Lift out half the onions onto paper towel for the top."},{"text":"Add the cumin, cinnamon and allspice to the onions left in the pan for 30 seconds. Stir in the rice, lentils, salt and water. Bring to the boil, cover tightly and cook on the lowest heat for 15 minutes. Rest off the heat, covered, for 10 minutes."},{"text":"Toss the salad ingredients together."},{"text":"Fluff the mujadara with a fork, pile onto a platter and top with the crispy onions. Serve with the salad and a spoonful of yoghurt if you like."}],"notes":["The onions are the whole dish. Take them darker than feels right, just short of burnt.","Leave out the yoghurt, or use a plant-based one, to keep it vegan."],"source":"user","provenance":"ai-draft"}},{"slug":"chermoula-fish-couscous","title":"Chermoula Fish with Herbed Couscous","cuisine":"north-african","meal_types":["dinner"],"diets":["pescatarian","no-dairy"],"difficulty":"easy","total_minutes":30,"recipe":{"id":"chermoula-fish-couscous","title":"Chermoula Fish with Herbed Couscous","summary":"White fish roasted under a punchy herb, lemon and cumin chermoula, with herby couscous.","cuisine":"north-african","diets":["pescatarian","no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":15,"cookMinutes":15,"servings":4,"onePot":false,"seasons":["spring","summer"],"ingredientGroups":[{"title":"Chermoula","items":[{"item":"coriander","raw":"1 bunch coriander, leaves and tender stems","quantity":1,"unit":"bunch","ingredientId":"coriander","prep":"leaves and tender stems"},{"item":"flat-leaf parsley leaves","raw":"1/2 bunch flat-leaf parsley leaves","quantity":0.5,"unit":"bunch","ingredientId":"parsley"},{"item":"garlic","raw":"2 garlic cloves","quantity":2,"unit":"clove","ingredientId":"garlic"},{"item":"ground cumin","raw":"2 tsp ground cumin","quantity":2,"unit":"tsp","ingredientId":"ground-cumin"},{"item":"smoked paprika","raw":"1 tsp smoked paprika","quantity":1,"unit":"tsp","ingredientId":"smoked-paprika"},{"item":"chilli flakes","raw":"1/4 tsp chilli flakes","quantity":0.25,"unit":"tsp","ingredientId":"chilli-flakes"},{"item":"lemon","raw":"Zest and juice of 1 lemon","quantity":1,"ingredientId":"lemon","prep":"zested and juiced"},{"item":"olive oil","raw":"80ml olive oil","quantity":80,"unit":"ml","ingredientId":"olive-oil"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"}]},{"title":"Fish","items":[{"item":"skinless barramundi","raw":"4 skinless barramundi fillets (about 160g each)","quantity":4,"unit":"fillet","ingredientId":"white-fish","note":"about 160g each"},{"item":"lemon","raw":"1 lemon, cut into wedges","quantity":1,"ingredientId":"lemon","prep":"cut into wedges"}]},{"title":"Couscous","items":[{"item":"couscous","raw":"300g couscous","quantity":300,"unit":"g","ingredientId":"couscous"},{"item":"boiling water","raw":"375ml boiling water","quantity":375,"unit":"ml","ingredientId":"water"},{"item":"olive oil","raw":"1 tbsp olive oil","quantity":1,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"cherry tomatoes","raw":"250g cherry tomatoes, halved","quantity":250,"unit":"g","ingredientId":"cherry-tomato","prep":"halved"},{"item":"Lebanese cucumber","raw":"1 Lebanese cucumber, diced","quantity":1,"ingredientId":"cucumber","prep":"diced"},{"item":"preserved lemon","raw":"1/2 preserved lemon, rind only, finely chopped (optional)","quantity":0.5,"ingredientId":"preserved-lemon","prep":"rind only, finely chopped","optional":true}]}],"steps":[{"text":"Heat the oven to 200°C (180°C fan-forced) and line a tray with baking paper."},{"text":"Blitz all the chermoula ingredients in a small food processor to a loose, chunky paste (or chop finely by hand and stir together)."},{"text":"Put the fish on the tray and spread each fillet with a heaped tablespoon of chermoula. Bake for 10 to 12 minutes, until the fish is opaque and flakes easily."},{"text":"Meanwhile, put the couscous, boiling water, oil and salt in a bowl. Cover and leave for 5 minutes, then fluff with a fork. Stir in the tomato, cucumber, preserved lemon and 2 tbsp of the chermoula."},{"text":"Serve the fish on the couscous with lemon wedges and the rest of the chermoula on the side."}],"notes":["Chermoula is also a great marinade for chicken or prawns. It keeps for 3 days in the fridge with a layer of oil on top.","Snapper, ling or blue-eye work as well as barramundi.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"source":"user","provenance":"ai-draft"}},{"slug":"groundnut-stew","title":"Groundnut Stew","cuisine":"west-african","meal_types":["dinner"],"diets":["no-gluten","no-dairy"],"difficulty":"easy","total_minutes":60,"recipe":{"id":"groundnut-stew","title":"Groundnut Stew","summary":"West African chicken and sweet potato stew in a rich, gently spiced peanut and tomato sauce.","cuisine":"west-african","diets":["no-gluten","no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":15,"cookMinutes":45,"servings":4,"onePot":true,"seasons":["autumn","winter"],"ingredientGroups":[{"items":[{"item":"neutral oil","raw":"1 tbsp neutral oil","quantity":1,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"chicken thigh fillets","raw":"700g chicken thigh fillets, cut into large chunks","quantity":700,"unit":"g","ingredientId":"chicken-thigh","prep":"cut into large chunks"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"brown onion","raw":"1 brown onion, diced","quantity":1,"ingredientId":"brown-onion","prep":"diced"},{"item":"garlic","raw":"3 garlic cloves, crushed","quantity":3,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"grated ginger","raw":"1 tbsp grated ginger","quantity":1,"unit":"tbsp","ingredientId":"ginger"},{"item":"long red chilli","raw":"1 long red chilli, finely chopped","quantity":1,"ingredientId":"red-chilli","prep":"finely chopped"},{"item":"ground cumin","raw":"1 tsp ground cumin","quantity":1,"unit":"tsp","ingredientId":"ground-cumin"},{"item":"ground coriander","raw":"1 tsp ground coriander","quantity":1,"unit":"tsp","ingredientId":"ground-coriander"},{"item":"tomato paste","raw":"2 tbsp tomato paste","quantity":2,"unit":"tbsp","ingredientId":"tomato-paste"},{"item":"crushed tomatoes","raw":"400g tin crushed tomatoes","quantity":400,"unit":"g","ingredientId":"tinned-tomatoes","note":"tin"},{"item":"smooth peanut butter","raw":"125g smooth peanut butter","quantity":125,"unit":"g","ingredientId":"peanut-butter"},{"item":"chicken stock","raw":"500ml chicken stock","quantity":500,"unit":"ml","ingredientId":"chicken-stock"},{"item":"sweet potato","raw":"500g sweet potato, peeled and cut into 3cm chunks","quantity":500,"unit":"g","ingredientId":"sweet-potato","prep":"peeled and cut into 3cm chunks"},{"item":"baby spinach","raw":"100g baby spinach","quantity":100,"unit":"g","ingredientId":"baby-spinach"},{"item":"roasted peanuts","raw":"2 tbsp roasted peanuts, chopped","quantity":2,"unit":"tbsp","ingredientId":"peanuts","prep":"chopped"},{"item":"coriander leaves","raw":"Handful of coriander leaves","quantity":1,"unit":"handful","ingredientId":"coriander"}]},{"title":"To serve","items":[{"item":"Steamed white rice","raw":"Steamed white rice","ingredientId":"white-rice"}]}],"steps":[{"text":"Heat the oil in a large heavy pot over medium-high heat. Season the chicken with half the salt and brown in two batches, 4 minutes per batch. Lift onto a plate."},{"text":"Turn the heat to medium. Cook the onion for 5 minutes until soft, then add the garlic, ginger, chilli, cumin and ground coriander for 1 minute."},{"text":"Stir in the tomato paste for 1 minute, then the tomatoes. Whisk in the peanut butter and stock until smooth."},{"text":"Add the chicken, sweet potato and remaining salt. Bring to a simmer, cover and cook gently for 25 to 30 minutes, stirring now and then so it doesn't catch, until the sweet potato is tender and the chicken is cooked through."},{"text":"Stir in the spinach until wilted. Taste for salt. Scatter with peanuts and coriander and serve over rice."}],"notes":["Contains peanuts.","Swap the chicken for 2 tins of drained chickpeas and use vegetable stock for a vegan pot.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"source":"user","provenance":"ai-draft"}},{"slug":"cape-malay-chicken-curry","title":"Cape Malay Chicken Curry","cuisine":"south-african","meal_types":["dinner"],"diets":["no-gluten","no-dairy"],"difficulty":"easy","total_minutes":65,"recipe":{"id":"cape-malay-chicken-curry","title":"Cape Malay Chicken Curry","summary":"A fragrant, mild and slightly sweet Cape Town curry with chicken, potato and apricot.","cuisine":"south-african","diets":["no-gluten","no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":15,"cookMinutes":50,"servings":4,"onePot":true,"seasons":["autumn","winter"],"ingredientGroups":[{"title":"Curry","items":[{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"cinnamon","raw":"1 cinnamon stick","quantity":1,"unit":"stick","ingredientId":"cinnamon-stick"},{"item":"cardamom pods","raw":"4 cardamom pods, lightly crushed","quantity":4,"ingredientId":"cardamom-pods","prep":"lightly crushed"},{"item":"bay","raw":"2 bay leaves","quantity":2,"unit":"leaf","ingredientId":"bay-leaf"},{"item":"brown onions","raw":"2 brown onions, finely diced","quantity":2,"ingredientId":"brown-onion","prep":"finely diced"},{"item":"garlic","raw":"4 garlic cloves, crushed","quantity":4,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"grated ginger","raw":"1 tbsp grated ginger","quantity":1,"unit":"tbsp","ingredientId":"ginger"},{"item":"mild curry powder","raw":"2 tbsp mild curry powder","quantity":2,"unit":"tbsp","ingredientId":"curry-powder"},{"item":"ground turmeric","raw":"1 tsp ground turmeric","quantity":1,"unit":"tsp","ingredientId":"ground-turmeric"},{"item":"ground cumin","raw":"1 tsp ground cumin","quantity":1,"unit":"tsp","ingredientId":"ground-cumin"},{"item":"ground coriander","raw":"1 tsp ground coriander","quantity":1,"unit":"tsp","ingredientId":"ground-coriander"},{"item":"chicken thigh fillets","raw":"800g chicken thigh fillets, cut into large chunks","quantity":800,"unit":"g","ingredientId":"chicken-thigh","prep":"cut into large chunks"},{"item":"crushed tomatoes","raw":"400g tin crushed tomatoes","quantity":400,"unit":"g","ingredientId":"tinned-tomatoes","note":"tin"},{"item":"waxy potatoes","raw":"400g waxy potatoes, cut into 3cm chunks","quantity":400,"unit":"g","ingredientId":"waxy-potato","prep":"cut into 3cm chunks"},{"item":"chicken stock","raw":"375ml chicken stock","quantity":375,"unit":"ml","ingredientId":"chicken-stock"},{"item":"apricot jam","raw":"2 tbsp apricot jam","quantity":2,"unit":"tbsp","ingredientId":"apricot-jam"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"lemon juice","raw":"1 tbsp lemon juice","quantity":1,"unit":"tbsp","ingredientId":"lemon"}]},{"title":"To serve","items":[{"item":"Steamed basmati rice","raw":"Steamed basmati rice","ingredientId":"basmati-rice"},{"item":"Mango chutney","raw":"Mango chutney","ingredientId":"mango-chutney"},{"item":"coriander leaves","raw":"Handful of coriander leaves","quantity":1,"unit":"handful","ingredientId":"coriander"}]}],"steps":[{"text":"Heat the oil in a large heavy pot over medium heat. Add the cinnamon, cardamom and bay and let them sizzle for 30 seconds."},{"text":"Add the onions and cook for 10 minutes, stirring, until soft and golden. Add the garlic and ginger for 1 minute, then the curry powder, turmeric, cumin and coriander for 1 minute more. Add a splash of water if the spices start to catch."},{"text":"Add the chicken and stir to coat in the spices for 2 minutes."},{"text":"Add the tomatoes, potatoes, stock, jam and salt. Bring to a simmer, cover and cook gently for 30 minutes, until the potatoes are tender and the chicken is cooked through. Uncover for the last 5 minutes if the sauce needs thickening."},{"text":"Stir in the lemon juice and taste: it should be warm, fragrant and just a little sweet. Remove the cinnamon stick and bay leaves. Serve with rice, chutney and coriander."}],"notes":["Cape Malay curries are fragrant rather than fiery. Add a chopped green chilli with the garlic if you like heat.","Sambals are the traditional sides: grated carrot with lemon, or tomato and onion with a little vinegar.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"source":"user","provenance":"ai-draft"}},{"slug":"aloo-gobi","title":"Aloo Gobi","cuisine":"indian","meal_types":["dinner","lunch"],"diets":["vegetarian","vegan","no-gluten","no-dairy"],"difficulty":"easy","total_minutes":50,"recipe":{"id":"aloo-gobi","title":"Aloo Gobi","summary":"Potato and cauliflower cooked with cumin, turmeric, ginger and tomato until golden and tender.","cuisine":"indian","diets":["vegetarian","vegan","no-gluten","no-dairy"],"mealTypes":["dinner","lunch"],"difficulty":"easy","prepMinutes":15,"cookMinutes":35,"servings":4,"onePot":true,"seasons":["autumn","winter"],"ingredientGroups":[{"items":[{"item":"neutral oil","raw":"3 tbsp neutral oil","quantity":3,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"cumin seeds","raw":"1 tsp cumin seeds","quantity":1,"unit":"tsp","ingredientId":"cumin-seeds"},{"item":"brown onion","raw":"1 brown onion, finely diced","quantity":1,"ingredientId":"brown-onion","prep":"finely diced"},{"item":"garlic","raw":"3 garlic cloves, crushed","quantity":3,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"grated ginger","raw":"1 tbsp grated ginger","quantity":1,"unit":"tbsp","ingredientId":"ginger"},{"item":"green chilli","raw":"1 green chilli, finely chopped","quantity":1,"ingredientId":"green-chilli","prep":"finely chopped"},{"item":"ground turmeric","raw":"1 tsp ground turmeric","quantity":1,"unit":"tsp","ingredientId":"ground-turmeric"},{"item":"ground coriander","raw":"2 tsp ground coriander","quantity":2,"unit":"tsp","ingredientId":"ground-coriander"},{"item":"Kashmiri chilli powder","raw":"1/2 tsp Kashmiri chilli powder","quantity":0.5,"unit":"tsp","ingredientId":"kashmiri-chilli-powder"},{"item":"tomatoes","raw":"2 tomatoes, finely chopped","quantity":2,"ingredientId":"tomato","prep":"finely chopped"},{"item":"potatoes","raw":"500g potatoes, peeled and cut into 2.5cm cubes","quantity":500,"unit":"g","ingredientId":"potato","prep":"peeled and cut into 2.5cm cubes"},{"item":"small cauliflower","raw":"1 small cauliflower (about 700g), cut into florets","quantity":1,"ingredientId":"cauliflower","prep":"cut into florets","note":"about 700g"},{"item":"salt","raw":"1 1/2 tsp salt","quantity":1.5,"unit":"tsp","ingredientId":"salt"},{"item":"water","raw":"125ml water","quantity":125,"unit":"ml","ingredientId":"water"},{"item":"garam masala","raw":"1 tsp garam masala","quantity":1,"unit":"tsp","ingredientId":"garam-masala"},{"item":"coriander leaves","raw":"Handful of coriander leaves, chopped","quantity":1,"unit":"handful","ingredientId":"coriander","prep":"chopped"},{"item":"lemon","raw":"Juice of 1/2 lemon","quantity":0.5,"ingredientId":"lemon","prep":"juiced"}]},{"title":"To serve","items":[{"item":"Steamed basmati rice","raw":"Steamed basmati rice","ingredientId":"basmati-rice"}]}],"steps":[{"text":"Heat the oil in a large deep frying pan or wide pot with a lid over medium heat. Add the cumin seeds and let them sizzle for 30 seconds."},{"text":"Add the onion and cook for 6 minutes until golden. Add the garlic, ginger and green chilli for 1 minute, then the turmeric, ground coriander and chilli powder for 30 seconds."},{"text":"Add the tomato and cook for 4 minutes, until it breaks down into a paste."},{"text":"Add the potato, cauliflower and salt and stir until everything is coated. Pour in the water, cover and cook over medium-low heat for 15 minutes, stirring gently once or twice."},{"text":"Uncover, turn the heat up to medium and cook for 5 to 8 minutes more, turning gently, until the vegetables are tender and catching golden at the edges."},{"text":"Sprinkle with garam masala, coriander and lemon juice. Serve with rice."}],"notes":["Don't stir too much or the cauliflower breaks up. Turn it with a flat spatula.","A handful of frozen peas in the last 5 minutes makes it go further."],"source":"user","provenance":"ai-draft"}},{"slug":"keema-matar","title":"Keema Matar","cuisine":"indian","meal_types":["dinner"],"diets":["no-gluten","no-dairy"],"difficulty":"easy","total_minutes":40,"recipe":{"id":"keema-matar","title":"Keema Matar","summary":"Spiced lamb mince and peas in a quick, rich tomato masala: a weeknight curry in 40 minutes.","cuisine":"indian","diets":["no-gluten","no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":10,"cookMinutes":30,"servings":4,"onePot":true,"ingredientGroups":[{"items":[{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"cumin seeds","raw":"1 tsp cumin seeds","quantity":1,"unit":"tsp","ingredientId":"cumin-seeds"},{"item":"large brown onion","raw":"1 large brown onion, finely diced","quantity":1,"ingredientId":"brown-onion","prep":"finely diced"},{"item":"garlic","raw":"4 garlic cloves, crushed","quantity":4,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"grated ginger","raw":"1 tbsp grated ginger","quantity":1,"unit":"tbsp","ingredientId":"ginger"},{"item":"green chilli","raw":"1 green chilli, finely chopped","quantity":1,"ingredientId":"green-chilli","prep":"finely chopped"},{"item":"lamb mince","raw":"500g lamb mince (or beef mince)","quantity":500,"unit":"g","ingredientId":"lamb-mince","note":"or beef mince"},{"item":"ground coriander","raw":"2 tsp ground coriander","quantity":2,"unit":"tsp","ingredientId":"ground-coriander"},{"item":"ground cumin","raw":"1 tsp ground cumin","quantity":1,"unit":"tsp","ingredientId":"ground-cumin"},{"item":"ground turmeric","raw":"1/2 tsp ground turmeric","quantity":0.5,"unit":"tsp","ingredientId":"ground-turmeric"},{"item":"Kashmiri chilli powder","raw":"1 tsp Kashmiri chilli powder","quantity":1,"unit":"tsp","ingredientId":"kashmiri-chilli-powder"},{"item":"crushed tomatoes","raw":"400g tin crushed tomatoes","quantity":400,"unit":"g","ingredientId":"tinned-tomatoes","note":"tin"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"water","raw":"125ml water","quantity":125,"unit":"ml","ingredientId":"water"},{"item":"frozen peas","raw":"200g frozen peas","quantity":200,"unit":"g","ingredientId":"frozen-peas"},{"item":"garam masala","raw":"1 tsp garam masala","quantity":1,"unit":"tsp","ingredientId":"garam-masala"},{"item":"coriander leaves","raw":"Handful of coriander leaves, chopped","quantity":1,"unit":"handful","ingredientId":"coriander","prep":"chopped"}]},{"title":"To serve","items":[{"item":"Steamed basmati rice","raw":"Steamed basmati rice","ingredientId":"basmati-rice"},{"item":"Lemon wedges","raw":"Lemon wedges","ingredientId":"lemon"}]}],"steps":[{"text":"Heat the oil in a large deep frying pan over medium heat. Add the cumin seeds and let them sizzle for 30 seconds, then add the onion and cook for 8 minutes until golden."},{"text":"Add the garlic, ginger and chilli for 1 minute."},{"text":"Turn the heat up to high, add the mince and cook for 6 to 8 minutes, breaking it up, until browned all over and any liquid has cooked off."},{"text":"Stir in the ground coriander, cumin, turmeric and chilli powder for 1 minute. Add the tomatoes, salt and water. Simmer for 12 minutes, stirring now and then, until thick and the oil starts to separate at the edges."},{"text":"Add the peas and cook for 3 minutes. Stir in the garam masala and coriander. Serve with rice and lemon wedges."}],"notes":["Mince must be cooked right through, with no pink left.","Wrap leftovers in warm roti with a spoon of yoghurt for lunch.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"source":"user","provenance":"ai-draft"}},{"slug":"shaking-beef","title":"Vietnamese Shaking Beef","cuisine":"vietnamese","meal_types":["dinner"],"diets":["no-dairy"],"difficulty":"easy","total_minutes":50,"recipe":{"id":"shaking-beef","title":"Vietnamese Shaking Beef","summary":"Seared cubes of garlicky, peppery beef tossed hot over a crisp, tangy salad.","cuisine":"vietnamese","diets":["no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":40,"cookMinutes":10,"servings":4,"onePot":false,"seasons":["spring","summer"],"ingredientGroups":[{"title":"Beef","items":[{"item":"beef rump steak","raw":"700g beef rump steak, cut into 2.5cm cubes","quantity":700,"unit":"g","ingredientId":"beef-rump","prep":"cut into 2.5cm cubes"},{"item":"garlic","raw":"3 garlic cloves, crushed","quantity":3,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"oyster sauce","raw":"2 tbsp oyster sauce","quantity":2,"unit":"tbsp","ingredientId":"oyster-sauce"},{"item":"soy sauce","raw":"1 tbsp soy sauce","quantity":1,"unit":"tbsp","ingredientId":"soy-sauce"},{"item":"fish sauce","raw":"1 tbsp fish sauce","quantity":1,"unit":"tbsp","ingredientId":"fish-sauce"},{"item":"brown sugar","raw":"2 tsp brown sugar","quantity":2,"unit":"tsp","ingredientId":"brown-sugar"},{"item":"black pepper","raw":"1 tsp black pepper","quantity":1,"unit":"tsp","ingredientId":"black-pepper"},{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"red onion","raw":"1 red onion, cut into wedges","quantity":1,"ingredientId":"red-onion","prep":"cut into wedges"}]},{"title":"Salad","items":[{"item":"rocket","raw":"120g rocket","quantity":120,"unit":"g","ingredientId":"rocket"},{"item":"cherry tomatoes","raw":"250g cherry tomatoes, halved","quantity":250,"unit":"g","ingredientId":"cherry-tomato","prep":"halved"},{"item":"Lebanese cucumber","raw":"1 Lebanese cucumber, sliced","quantity":1,"ingredientId":"cucumber","prep":"sliced"},{"item":"rice vinegar","raw":"2 tbsp rice vinegar","quantity":2,"unit":"tbsp","ingredientId":"rice-vinegar"},{"item":"sugar","raw":"1 tsp sugar","quantity":1,"unit":"tsp","ingredientId":"sugar"}]},{"title":"Lime pepper dip","items":[{"item":"limes","raw":"Juice of 2 limes","quantity":2,"ingredientId":"lime","prep":"juiced"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"black pepper","raw":"1/2 tsp black pepper","quantity":0.5,"unit":"tsp","ingredientId":"black-pepper"}]},{"title":"To serve","items":[{"item":"Steamed jasmine rice","raw":"Steamed jasmine rice","ingredientId":"jasmine-rice"}]}],"steps":[{"text":"Toss the beef with the garlic, oyster sauce, soy sauce, fish sauce, sugar and pepper. Marinate for 30 minutes at room temperature, or up to 4 hours in the fridge."},{"text":"Mix the vinegar and sugar, toss with the rocket, tomato and cucumber, and spread over a platter. Stir the lime juice, salt and pepper together in a small dish."},{"text":"Heat a large heavy frying pan or wok over very high heat until smoking. Add half the oil and half the beef in a single layer. Leave it for 1 minute to sear, then shake the pan to turn the cubes and cook for 1 minute more. Tip onto a plate and repeat with the rest."},{"text":"Return all the beef to the pan with the onion. Shake and toss for 1 minute, until the onion just softens and the beef is glossy and medium-rare."},{"text":"Pile the beef and pan juices over the salad. Serve with rice and the lime pepper dip."}],"notes":["A very hot pan and small batches are what make the crust. Crowd the pan and the beef stews.","Watercress is the traditional base. Use it in place of the rocket if you can find it.","Food safety: Steaks and roasting cuts of beef or lamb can be served pink: about 60°C in the centre is medium-rare, 70°C is well done."],"source":"user","provenance":"ai-draft"}},{"slug":"tomato-egg-stir-fry","title":"Tomato and Egg Stir-Fry","cuisine":"chinese","meal_types":["dinner","lunch"],"diets":["vegetarian","no-dairy"],"difficulty":"easy","total_minutes":20,"recipe":{"id":"tomato-egg-stir-fry","title":"Tomato and Egg Stir-Fry","summary":"Soft, fluffy eggs folded through sweet, saucy tomatoes: China's favourite home dinner.","cuisine":"chinese","diets":["vegetarian","no-dairy"],"mealTypes":["dinner","lunch"],"difficulty":"easy","prepMinutes":10,"cookMinutes":10,"servings":4,"onePot":false,"seasons":["summer","autumn"],"ingredientGroups":[{"items":[{"item":"eggs","raw":"8 eggs","quantity":8,"ingredientId":"egg"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"sesame oil","raw":"1 tsp sesame oil","quantity":1,"unit":"tsp","ingredientId":"sesame-oil"},{"item":"neutral oil","raw":"3 tbsp neutral oil","quantity":3,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"ripe tomatoes","raw":"600g ripe tomatoes, cut into wedges","quantity":600,"unit":"g","ingredientId":"tomato","prep":"cut into wedges"},{"item":"garlic","raw":"2 garlic cloves, finely chopped","quantity":2,"unit":"clove","ingredientId":"garlic","prep":"finely chopped"},{"item":"tomato sauce","raw":"2 tbsp tomato sauce","quantity":2,"unit":"tbsp","ingredientId":"tomato-sauce"},{"item":"sugar","raw":"2 tsp sugar","quantity":2,"unit":"tsp","ingredientId":"sugar"},{"item":"water","raw":"60ml water","quantity":60,"unit":"ml","ingredientId":"water"},{"item":"cornflour","raw":"1 tsp cornflour, mixed with 1 tbsp water","quantity":1,"unit":"tsp","ingredientId":"cornflour","prep":"mixed with 1 tbsp water"},{"item":"spring onions","raw":"3 spring onions, sliced","quantity":3,"ingredientId":"spring-onion","prep":"sliced"}]},{"title":"To serve","items":[{"item":"Steamed jasmine rice","raw":"Steamed jasmine rice","ingredientId":"jasmine-rice"}]}],"steps":[{"text":"Beat the eggs with half the salt and the sesame oil until smooth."},{"text":"Heat 2 tbsp of the neutral oil in a wok or large frying pan over medium-high heat. Pour in the eggs, let them set for a few seconds, then push them gently around the pan into large, soft curds. Take them out after about 1 minute, while still a little wet; they'll finish cooking in the sauce."},{"text":"Add the rest of the oil and the garlic and stir for 20 seconds. Add the tomatoes and cook for 3 to 4 minutes, pressing some with the spatula, until they soften and release their juice."},{"text":"Stir in the tomato sauce, sugar, remaining salt and water and bubble for 1 minute. Stir in the cornflour mixture until the sauce turns glossy."},{"text":"Return the eggs and fold through for 1 minute, until just set all the way through. Scatter with spring onion and serve straight away over rice."}],"notes":["Ripe, juicy tomatoes make the sauce. In winter, use 400g ripe tomatoes and 200g tinned crushed tomatoes.","Much Australian cornflour is made from wheat. Use one labelled maize and gluten-free for a gluten-free plate.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"source":"user","provenance":"ai-draft"}},{"slug":"steamed-fish-ginger-spring-onion","title":"Steamed Fish with Ginger and Spring Onion","cuisine":"chinese","meal_types":["dinner"],"diets":["pescatarian","no-dairy"],"difficulty":"easy","total_minutes":25,"recipe":{"id":"steamed-fish-ginger-spring-onion","title":"Steamed Fish with Ginger and Spring Onion","summary":"Tender steamed fish under a crackle of hot oil, ginger, spring onion and soy.","cuisine":"chinese","diets":["pescatarian","no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":10,"cookMinutes":15,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Fish","items":[{"item":"skinless snapper","raw":"4 skinless snapper fillets (about 160g each)","quantity":4,"unit":"fillet","ingredientId":"white-fish","note":"about 160g each"},{"item":"piece ginger","raw":"5cm piece ginger, half sliced, half cut into fine matchsticks","quantity":5,"unit":"cm","ingredientId":"ginger","prep":"half sliced, half cut into fine matchsticks"},{"item":"Shaoxing wine","raw":"1 tbsp Shaoxing wine (optional)","quantity":1,"unit":"tbsp","ingredientId":"shaoxing-wine","optional":true},{"item":"spring onions","raw":"4 spring onions, cut into fine strips","quantity":4,"ingredientId":"spring-onion","prep":"cut into fine strips"},{"item":"coriander sprigs","raw":"Handful of coriander sprigs","quantity":1,"unit":"handful","ingredientId":"coriander"}]},{"title":"Sauce","items":[{"item":"soy sauce","raw":"3 tbsp soy sauce","quantity":3,"unit":"tbsp","ingredientId":"soy-sauce"},{"item":"water","raw":"1 tbsp water","quantity":1,"unit":"tbsp","ingredientId":"water"},{"item":"sugar","raw":"1 tsp sugar","quantity":1,"unit":"tsp","ingredientId":"sugar"},{"item":"neutral oil","raw":"60ml neutral oil","quantity":60,"unit":"ml","ingredientId":"neutral-oil"}]},{"title":"To serve","items":[{"item":"Steamed jasmine rice","raw":"Steamed jasmine rice","ingredientId":"jasmine-rice"},{"item":"bok choy","raw":"1 bunch bok choy, halved and steamed","quantity":1,"unit":"bunch","ingredientId":"bok-choy","prep":"halved and steamed"}]}],"steps":[{"text":"Set up a steamer: a wok or wide pot with a rack and a lid, with 5cm of water, brought to a rolling boil."},{"text":"Lay the ginger slices on a heatproof plate that fits in the steamer, put the fish on top and drizzle with the Shaoxing wine."},{"text":"Steam the fish for 8 to 10 minutes, until it's opaque and flakes easily at the thickest part. Carefully lift the plate out and pour off the liquid that has collected."},{"text":"Warm the soy sauce, water and sugar in a small pan until the sugar dissolves, then pour over and around the fish. Top with the ginger matchsticks and spring onion."},{"text":"Heat the oil in a small pan until it shimmers and just starts to smoke. Carefully pour it over the ginger and spring onion; it will sizzle loudly. Top with coriander and serve with rice and bok choy."}],"notes":["Hot oil spits: pour it slowly and keep your face back.","Use tamari in place of soy sauce, and leave out the Shaoxing, for a gluten-free plate.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"source":"user","provenance":"ai-draft"}},{"slug":"ginger-pork-shogayaki","title":"Ginger Pork (Shogayaki)","cuisine":"japanese","meal_types":["dinner","lunch"],"diets":["no-dairy"],"difficulty":"easy","total_minutes":25,"recipe":{"id":"ginger-pork-shogayaki","title":"Ginger Pork (Shogayaki)","summary":"Thin pork slices glazed in ginger, soy and mirin, with shredded cabbage and rice.","cuisine":"japanese","diets":["no-dairy"],"mealTypes":["dinner","lunch"],"difficulty":"easy","prepMinutes":15,"cookMinutes":10,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Sauce","items":[{"item":"grated ginger","raw":"2 tbsp grated ginger","quantity":2,"unit":"tbsp","ingredientId":"ginger"},{"item":"soy sauce","raw":"60ml soy sauce","quantity":60,"unit":"ml","ingredientId":"soy-sauce"},{"item":"mirin","raw":"60ml mirin","quantity":60,"unit":"ml","ingredientId":"mirin"},{"item":"sake","raw":"2 tbsp sake","quantity":2,"unit":"tbsp","ingredientId":"sake"},{"item":"sugar","raw":"2 tsp sugar","quantity":2,"unit":"tsp","ingredientId":"sugar"}]},{"title":"Pork","items":[{"item":"pork neck","raw":"600g pork neck (pork scotch), very thinly sliced","quantity":600,"unit":"g","ingredientId":"pork-shoulder","prep":"very thinly sliced","note":"pork scotch"},{"item":"plain flour","raw":"1 tbsp plain flour","quantity":1,"unit":"tbsp","ingredientId":"plain-flour"},{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"brown onion","raw":"1 brown onion, thinly sliced","quantity":1,"ingredientId":"brown-onion","prep":"thinly sliced"}]},{"title":"To serve","items":[{"item":"cabbage","raw":"1/4 cabbage, very finely shredded","quantity":0.25,"ingredientId":"cabbage","prep":"very finely shredded"},{"item":"Steamed short-grain rice","raw":"Steamed short-grain rice","ingredientId":"sushi-rice"},{"item":"Kewpie mayonnaise","raw":"Kewpie mayonnaise (optional)","ingredientId":"kewpie-mayonnaise","optional":true},{"item":"sesame seeds","raw":"1 tsp sesame seeds","quantity":1,"unit":"tsp","ingredientId":"sesame-seeds"}]}],"steps":[{"text":"Mix the sauce ingredients in a bowl."},{"text":"Lightly dust the pork with the flour. This helps the sauce cling."},{"text":"Heat half the oil in a large frying pan over high heat. Lay in half the pork in a single layer and cook for 1 minute each side until browned. Tip onto a plate and repeat with the rest of the oil and pork."},{"text":"Add the onion to the pan and cook for 2 minutes until it starts to soften. Return all the pork, pour in the sauce and toss for 1 to 2 minutes, until the sauce is thick and glossy and the pork is cooked through."},{"text":"Pile the cabbage and rice on plates and add the pork with its sauce. Finish with sesame seeds and a little Kewpie if you like."}],"notes":["Freeze the pork for 30 minutes and it slices paper-thin with a sharp knife. Many Asian grocers sell it ready-sliced for shabu shabu.","The raw cabbage is the classic side: it soaks up the sauce and freshens every bite.","Food safety: Cook fresh pork to at least 70°C in the thickest part."],"source":"user","provenance":"ai-draft"}},{"slug":"miso-glazed-eggplant","title":"Miso-Glazed Eggplant","cuisine":"japanese","meal_types":["dinner","lunch"],"diets":["vegetarian","vegan","no-dairy"],"difficulty":"easy","total_minutes":45,"recipe":{"id":"miso-glazed-eggplant","title":"Miso-Glazed Eggplant","summary":"Silky roasted eggplant under a bubbling sweet miso glaze, with rice and greens.","cuisine":"japanese","diets":["vegetarian","vegan","no-dairy"],"mealTypes":["dinner","lunch"],"difficulty":"easy","prepMinutes":10,"cookMinutes":35,"servings":4,"onePot":false,"seasons":["summer","autumn"],"ingredientGroups":[{"title":"Eggplant","items":[{"item":"medium eggplants","raw":"3 medium eggplants, halved lengthways","quantity":3,"ingredientId":"eggplant","prep":"halved lengthways"},{"item":"neutral oil","raw":"3 tbsp neutral oil","quantity":3,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"salt","raw":"Pinch of salt","quantity":1,"unit":"pinch","ingredientId":"salt"}]},{"title":"Miso glaze","items":[{"item":"white miso","raw":"80g white miso","quantity":80,"unit":"g","ingredientId":"miso"},{"item":"mirin","raw":"2 tbsp mirin","quantity":2,"unit":"tbsp","ingredientId":"mirin"},{"item":"sake","raw":"1 tbsp sake","quantity":1,"unit":"tbsp","ingredientId":"sake"},{"item":"sugar","raw":"1 tbsp sugar","quantity":1,"unit":"tbsp","ingredientId":"sugar"},{"item":"grated ginger","raw":"1 tsp grated ginger","quantity":1,"unit":"tsp","ingredientId":"ginger"}]},{"title":"To serve","items":[{"item":"spring onions","raw":"2 spring onions, finely sliced","quantity":2,"ingredientId":"spring-onion","prep":"finely sliced"},{"item":"sesame seeds","raw":"2 tsp sesame seeds","quantity":2,"unit":"tsp","ingredientId":"sesame-seeds"},{"item":"Steamed short-grain rice","raw":"Steamed short-grain rice","ingredientId":"sushi-rice"},{"item":"baby bok choy","raw":"2 bunches baby bok choy, halved","quantity":2,"unit":"bunch","ingredientId":"bok-choy","prep":"halved"},{"item":"sesame oil","raw":"1 tsp sesame oil","quantity":1,"unit":"tsp","ingredientId":"sesame-oil"}]}],"steps":[{"text":"Heat the oven to 220°C (200°C fan-forced) and line a tray with baking paper."},{"text":"Score the cut side of each eggplant half in a deep criss-cross, without cutting through the skin. Brush the cut sides generously with oil, season with salt and lay cut side down on the tray."},{"text":"Roast for 25 minutes, until the flesh is completely soft when pressed."},{"text":"Meanwhile, stir the miso, mirin, sake, sugar and ginger in a small pan over low heat for 2 minutes until smooth and glossy."},{"text":"Turn the eggplants cut side up and spread with the glaze. Switch the oven to grill and grill for 3 to 5 minutes, watching closely, until bubbling and caramelised in spots."},{"text":"Steam or blanch the bok choy for 2 minutes and toss with the sesame oil. Scatter the eggplant with spring onion and sesame seeds and serve with rice and the greens."}],"notes":["Miso burns quickly under the grill. Don't walk away.","Most miso contains barley or wheat. Look for a rice-only miso if you need it gluten-free."],"source":"user","provenance":"ai-draft"}}]$q$::jsonb)), dn as (select r, row_number() over (partition by r->>'cuisine' order by r->>'slug') rn from d), cand as (select c.id, x.cuisine, row_number() over (partition by x.cuisine order by c.recipe_count, c.handle)-1 ix, count(*) over (partition by x.cuisine) cnt from public.cooks c join (select distinct cook_id, cuisine from public.published_recipes where status='published') x on x.cook_id=c.id where c.kind='person'), ins as (insert into public.published_recipes (cook_id,slug,title,cuisine,meal_types,diets,difficulty,total_minutes,recipe,review,status) select coalesce((select cd.id from cand cd where cd.cuisine=dn.r->>'cuisine' and cd.ix=(dn.rn-1)%cd.cnt),(select id from public.cooks where kind='official' limit 1)), dn.r->>'slug', dn.r->>'title', dn.r->>'cuisine', array(select jsonb_array_elements_text(dn.r->'meal_types')), array(select jsonb_array_elements_text(dn.r->'diets')), dn.r->>'difficulty', (dn.r->>'total_minutes')::int, jsonb_set(dn.r->'recipe','{notes}',coalesce((select jsonb_agg(n) from jsonb_array_elements(dn.r->'recipe'->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)), 'auto-checked','published' from dn where not exists (select 1 from public.published_recipes q where q.slug=dn.r->>'slug') on conflict do nothing returning id) select (select count(*) from d) expected, (select count(*) from ins) inserted;